# <<< STATIC

# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_zig_build_id() {
    printf '%s\n' fast sha1 tree md5 uuid none
    printf '0x\0\n'
}

_choice_zig_build_steps() {
    zig build --list-steps 2>/dev/null | gawk '
        /^  [^ ]/ {
            line = $0
            sub(/^[ \t]+/, "", line)
            name = line
            sub(/[ \t].*$/, "", name)
            rest = line
            sub(/^[^ \t]+/, "", rest)
            sub(/^[ \t]*\(default\)[ \t]*/, "", rest)
            sub(/^[ \t]+/, "", rest)
            printf "%s\t%s\n", name, rest
        }
    '
}

_choice_zig_cpu() {
    local arch="${argc_target:-}"
    arch="${arch%%-*}"
    local targets
    targets="$(zig targets 2>/dev/null)"
    if [[ -z "$arch" ]]; then
        arch="$(printf '%s\n' "$targets" | gawk '
            /^        \.triple = "/ {
                line = $0
                sub(/^        \.triple = "/, "", line)
                sub(/-.*$/, "", line)
                print line
                exit
            }
        ')"
    fi
    [[ -n "$arch" ]] || return 0
    printf '%s\n' "$targets" | gawk -v arch="$arch" '
        /^    \.cpus = \.\{/ { in_cpus = 1; next }
        in_cpus && $0 == "    }," { in_cpus = 0; next }
        in_cpus && index($0, "        ." arch " = .{") == 1 { in_arch = 1; next }
        in_arch && $0 == "        }," { exit }
        in_arch && match($0, /^            \.[A-Za-z0-9_.+-]+ = \.\{/) {
            name = substr($0, RSTART, RLENGTH)
            sub(/^            \./, "", name)
            sub(/ = .*$/, "", name)
            print name
        }
    '
}

_choice_zig_flto() {
    printf '%s\n' auto jobserver
}

_choice_zig_mprintf_kind() {
    printf '%s\n' hostcall buffered
}

_choice_zig_mrecip() {
    printf '%s\n' all default none
}

_choice_zig_sort_section() {
    printf '%s\n' name alignment
}

_choice_zig_target() {
    _argc_util_mode_parts -
    case "${argc__parts_len}" in
    1) _helper_zig_target_part arch ;;
    2) _helper_zig_target_part os ;;
    3) _helper_zig_target_part abi ;;
    esac
}

_choice_zig_z() {
    printf '%s\n' nodelete notext defs undefs origin nocopyreloc now lazy relro norelro
    printf 'common-page-size=\0\nmax-page-size=\0\n'
}

_helper_zig_target_part() {
    local key="$1"
    zig targets 2>/dev/null | gawk -v key="$key" '
        index($0, "    ." key " = .{") == 1 { inside = 1; next }
        inside && $0 == "    }," { exit }
        inside && match($0, /"[^"]+"/) { print substr($0, RSTART + 1, RLENGTH - 2) }
    '
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
